<template><div class="page"><div class="page-header"><h2>报警记录</h2></div><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="open"><el-table-column prop="rule_id" label="规则编号" width="100"/><el-table-column prop="eid" label="设备SN" width="130"/><el-table-column prop="data_type" label="数据类型" width="90"/><el-table-column prop="data_value" label="触发值" width="90"/><el-table-column label="严重度" width="80"><template #default="{row}"><el-tag :type="severityTag(row.severity)" size="small">{{ row.severity||'-' }}</el-tag></template></el-table-column><el-table-column label="状态" width="80"><template #default="{row}"><el-tag :type="alertStatusTag(row.status)" size="small">{{ row.status||'ACTIVE' }}</el-tag></template></el-table-column><el-table-column prop="alert_time" label="报警时间" width="110"/></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card><el-dialog :title="'报警详情'" v-model="drawer" width="500px"><template v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="规则编号">{{ detail.rule_id||'-' }}</el-descriptions-item><el-descriptions-item label="设备SN">{{ detail.eid||'-' }}</el-descriptions-item><el-descriptions-item label="数据类型">{{ detail.data_type||'-' }}</el-descriptions-item><el-descriptions-item label="触发值">{{ detail.data_value||'-' }}</el-descriptions-item><el-descriptions-item label="严重度"><el-tag :type="severityTag(detail.severity)" size="small">{{ detail.severity||'-' }}</el-tag></el-descriptions-item><el-descriptions-item label="状态"><el-tag :type="alertStatusTag(detail.status)" size="small">{{ detail.status||'ACTIVE' }}</el-tag></el-descriptions-item><el-descriptions-item label="报警时间">{{ detail.alert_time||'-' }}</el-descriptions-item><el-descriptions-item label="确认人">{{ detail.ack_user||'-' }}</el-descriptions-item><el-descriptions-item label="确认时间">{{ detail.ack_time||'-' }}</el-descriptions-item><el-descriptions-item label="解决时间">{{ detail.resolve_time||'-' }}</el-descriptions-item><el-descriptions-item label="备注" :span="2">{{ detail.remark||'-' }}</el-descriptions-item></el-descriptions></template></el-dialog></div></template>
<script setup lang="ts">import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {useDetailDrawer} from '@/composables/useDetailDrawer';import {fetchAlertLogs} from '@/api/iot';import type {IotRecord} from '@/api/iot'
const{items,loading,page,perPage,total}=useListPage<IotRecord>(fetchAlertLogs);const{drawer,detail,open}=useDetailDrawer<IotRecord>()
function severityTag(s:string){const m:Record<string,string>={INFO:'info',WARNING:'warning',CRITICAL:'danger'};return m[s]||'info'}
function alertStatusTag(s:string){const m:Record<string,string>={ACTIVE:'danger',ACKNOWLEDGED:'warning',RESOLVED:'success'};return m[s]||'info'}</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;margin-bottom:16px}.page-header h2{font-size:18px;font-weight:600;margin:0}</style>
